  test("overlapping usage events issue one metrics read at a time and converge on the newest", async () => {
    const { session, mockSession, signals } = await createAgentSession(disposables);
    session.resetTurnState("turn-overlapping");
    const slowFirstRead = new DeferredPromise();
    mockSession.usageMetricsGates.push(slowFirstRead.p);
    const fireUsage = (totalNanoAiu) => mockSession.fire("assistant.usage", {
      model: "claude-opus-4.6",
      inputTokens: 10,
      outputTokens: 20,
      copilotUsage: { totalNanoAiu }
    });
    fireUsage(5e8);
    await timeout(0);
    fireUsage(1e9);
    await timeout(0);
    fireUsage(5e8);
    await timeout(0);
    assert.strictEqual(mockSession.usageMetricsCalls, 1);
    slowFirstRead.complete();
    for (let i = 0; i < 5; i++) {
      await timeout(0);
    }
    assert.strictEqual(mockSession.usageMetricsCalls, 2);
    session.resetTurnState("turn-after-overlap");
    fireUsage(25e7);
    for (let i = 0; i < 5; i++) {
      await timeout(0);
    }
    const usageActions = getActions(signals).filter((a) => a.type === ActionType.ChatUsage);
    assert.strictEqual(
      usageActions.at(-1)?.usage._meta?.copilotUsage?.sessionTotalNanoAiu,
      225e7
    );
  });
